    ("${ic('falsch','s')}An</button><button data-r=\"0\" class=\"${radarOn()?'':'on'}\">Aus</button>", "${ic('falsch','s')}On</button><button data-r=\"0\" class=\"${radarOn()?'':'on'}\">Off</button>"),
    ('<h2>Darstellung und Speicherung</h2>', '<h2>Display and storage</h2>'),
