    ("${ic('dunkel','s')}Dunkel</button>", "${ic('dunkel','s')}Dark</button>"),
    ("Dein Fortschritt liegt ${Store.mode()==='cookie'?'in zwei Cookies (<code>mgk_p</code>, <code>mgk_m</code>, 1 Jahr gültig)':'im lokalen Browserspeicher (Cookies sind hier nicht verfügbar, etwa beim Öffnen als Datei)'} auf diesem Gerät. Außer für eine eingeschaltete Erinnerung (siehe oben) werden keine Daten an einen Server gesendet.",
     "Your progress is kept ${Store.mode()==='cookie'?'in two cookies (<code>mgk_p</code>, <code>mgk_m</code>, valid for 1 year)':'in local browser storage (cookies are not available here, e.g. when opened as a file)'} on this device, shared with the German version of IPelico. Apart from a reminder you switch on (see above), no data is sent to a server."),
    ("${ic('loeschung','m')}Fortschritt löschen</button>", "${ic('loeschung','m')}Delete progress</button>"),
    ('<h2>Fortschritt übertragen</h2><div class="glass card"><p style="margin:0 0 12px">Kopiere deinen Fortschritt als JSON und füge ihn auf einem anderen Gerät oder einer anderen IPelico-Seite hier ein. <b>Zusammenführen</b> behält je Fall die neuere Antwort, <b>Überschreiben</b> ersetzt den Fortschritt und die Einstellungen dieses Geräts.</p>',
     '<h2>Transfer progress</h2><div class="glass card"><p style="margin:0 0 12px">Copy your progress as JSON and paste it here on another device or another IPelico page. <b>Merge</b> keeps the newer answer for each case, <b>Overwrite</b> replaces this device’s progress and settings.</p>'),
    ("${ic('register','m')}Fortschritt kopieren</button>", "${ic('register','m')}Copy progress</button>"),
    ('aria-label="Fortschritt als JSON" placeholder=\'{"app":"ipelico","v":1, …} hier einfügen\'', 'aria-label="Progress as JSON" placeholder=\'Paste {"app":"ipelico","v":1, …} here\''),
    ('id="xmerge">Zusammenführen</button><button class="btn ghost" id="xover">Überschreiben</button>', 'id="xmerge">Merge</button><button class="btn ghost" id="xover">Overwrite</button>'),
    ("confirm('Gesamten Fortschritt löschen?')", "confirm('Delete all progress?')"),
    ("say(`Kopiert: ${Object.keys(P.u).length} bearbeitete Einheiten, ${P.xp} XP.`,true);", "say(`Copied: ${Object.keys(P.u).length} units worked on, ${P.xp} XP.`,true);"),
    ("say(ok?'Kopiert.':'Zwischenablage nicht verfügbar – der markierte Text unten lässt sich manuell kopieren.',ok);", "say(ok?'Copied.':'Clipboard not available – copy the selected text below manually.',ok);"),
    ("confirm('Fortschritt und Einstellungen dieses Geräts durch die eingefügten Daten ersetzen?')", "confirm('Replace this device’s progress and settings with the pasted data?')"),
